using System;
using System.Collections.Generic;
using ResolverMaster.Core.Puzzle;
using UnityEngine;

namespace ResolverMaster.Core.UI.Themes
{
    /// <summary>How the ground between and under the cells is drawn (generated by <see cref="ThemeArt"/>).</summary>
    public enum TerrainPattern
    {
        /// <summary>Grass with tufts; cells are light stone slabs (Garden).</summary>
        Grass,
        /// <summary>Beaten earth with straw (Farm).</summary>
        Dirt,
        /// <summary>Light grey sidewalk tiles (City).</summary>
        Pavement,
    }

    /// <summary>How the screen background is drawn (generated by <see cref="ThemeArt"/>).</summary>
    public enum BackdropPattern
    {
        /// <summary>Light sky on top, green meadow with soft hills and small flowers.</summary>
        Meadow,
        /// <summary>Warm sky, yellow and brown field stripes.</summary>
        Fields,
        /// <summary>Blue-grey sky with simple building silhouettes.</summary>
        Skyline,
    }

    /// <summary>
    /// The look of a Story chapter (ErNa-005): cell terrain, ground between the cells and screen background, plus an accent color.
    /// Everything is generated by code from these colors and the seed; the three image slots are where the Gemini drawings will go
    /// (a set image replaces the generated one). Terrains never use strong blue or orange: those are the water colors.
    /// </summary>
    [Serializable]
    public sealed class VisualTheme
    {
        /// <summary>Stable id referenced by the chapters of the games (e.g. "garden").</summary>
        public string id;
        /// <summary>Localization key of the theme name (core.txt), e.g. "theme.garden.name".</summary>
        public string nameKey;
        /// <summary>Banner and thumbnail accent.</summary>
        public Color accent = Color.white;
        public int seed = 1;

        [Header("Cells and ground")]
        public TerrainPattern terrain;
        /// <summary>Ground between the cells and its details (tufts, straw, joints).</summary>
        public Color ground = Color.green;
        public Color groundDetail = Color.green;
        /// <summary>Cell tile (slab), its details and its darker rim.</summary>
        public Color slab = Color.white;
        public Color slabDetail = Color.gray;
        public Color slabEdge = Color.gray;

        [Header("Screen background")]
        public BackdropPattern backdrop;
        public Color skyTop = Color.white;
        public Color skyBottom = Color.white;
        public Color landA = Color.green;
        public Color landB = Color.green;
        public Color landDetail = Color.white;

        [Header("Images (Gemini, later): when set they replace the generated art")]
        public Sprite slabImage;
        public Sprite groundImage;
        public Sprite backdropImage;
    }

    /// <summary>
    /// Finds the theme of a chapter (pure logic, tested in EditMode): the chapter names a theme id in its game's parameter file;
    /// an empty or unknown id gives the default theme.
    /// </summary>
    public sealed class ThemeCatalog
    {
        readonly List<VisualTheme> _themes;
        readonly string _defaultId;

        public ThemeCatalog(IEnumerable<VisualTheme> themes, string defaultId)
        {
            _themes = new List<VisualTheme>(themes ?? Array.Empty<VisualTheme>());
            _defaultId = defaultId;
        }

        public IReadOnlyList<VisualTheme> Themes => _themes;

        /// <summary>The default theme (the one named by the default id, else the first one, else null).</summary>
        public VisualTheme Default => Find(_defaultId) ?? (_themes.Count > 0 ? _themes[0] : null);

        /// <summary>The theme with this id, or null.</summary>
        public VisualTheme Find(string id)
        {
            if (string.IsNullOrEmpty(id)) return null;
            foreach (var t in _themes)
                if (t != null && t.id == id) return t;
            return null;
        }

        public bool Has(string id) => Find(id) != null;

        /// <summary>The theme with this id; the default one when the id is empty or unknown.</summary>
        public VisualTheme Get(string id) => Find(id) ?? Default;

        /// <summary>The theme of a Story chapter (its <see cref="ChapterTheme.theme"/> id), or the default.</summary>
        public VisualTheme ForChapter(StoryChapter chapter) => Get(chapter?.Theme?.theme);
    }
}
